B.KS=new A.bK("2. Hold and Wait \u2013 ",null,null,B.A,null,null,null,null,null,null,B.bD)
B.KT=new A.bK("A process holds a resource while waiting for others.\n",null,null,B.A,null,null,null,null,null,null,null)
B.L_=new A.bK("3. No Preemption \u2013 ",null,null,B.A,null,null,null,null,null,null,B.bD)
B.KZ=new A.bK("Resources can\u2019t be forcibly taken; they must be released voluntarily.\n",null,null,B.A,null,null,null,null,null,null,null)
B.L0=new A.bK("4. Circular Wait \u2013 ",null,null,B.A,null,null,null,null,null,null,B.bD)
B.KR=new A.bK("A cycle of processes, each waiting for the next to release a resource.\n\n",null,null,B.A,null,null,null,null,null,null,null)
B.KG=new A.bK("Deadlock solutions:\n\n",null,null,B.A,null,null,null,null,null,null,B.bD)
B.L2=new A.bK("- Limit the number of philosophers: ",null,null,B.A,null,null,null,null,null,null,null)
B.KF=new A.bK("Allow fewer philosophers than forks to break mutual exclusion.\n",null,null,B.A,null,null,null,null,null,null,null)
B.KK=new A.bK("- Pick both forks at once (critical section): ",null,null,B.A,null,null,null,null,null,null,null)
